package com.MapPlayerIndicator.overlay;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Objects;
import javax.imageio.ImageIO;
import javax.inject.Inject;

import com.MapPlayerIndicator.ImageUtil;
import com.MapPlayerIndicator.PlayerIndicatorConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

@Slf4j
public class PlayerIndicatorWorldMapOverlay
{
    private final Client client;
    private final PlayerIndicatorConfig config;
    private final WorldMapPointManager worldMapPointManager;

    private WorldMapPoint playerPoint;

    private BufferedImage baseArrow;   // original image

    @Inject
    public PlayerIndicatorWorldMapOverlay(
            Client client,
            PlayerIndicatorConfig config,
            WorldMapPointManager worldMapPointManager
    )
    {
        this.client = client;
        this.config = config;
        this.worldMapPointManager = worldMapPointManager;
    }

    public void startUp() {
        try {
            baseArrow = ImageIO.read(Objects.requireNonNull(getClass().getResourceAsStream("/arrow.png")));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        if (config.worldMapEnabled())
        {
            ensurePointExists();
        }
    }

    public void shutDown()
    {
        removePoint();
    }

    public void onGameTick()
    {
        if (!config.worldMapEnabled())
        {
            removePoint();
            return;
        }

        Player p = client.getLocalPlayer();
        if (p == null)
        {
            return;
        }

        ensurePointExists();

        if (playerPoint == null || baseArrow == null)
        {
            return;
        }

        // Update location
        playerPoint.setWorldPoint(p.getWorldLocation());

        // Rotate to true facing
        double theta = p.getCurrentOrientation() * Perspective.UNIT;

        BufferedImage rotatedScaled = ImageUtil.rotateAndScale(
                baseArrow,
                theta,
                config.worldMapIconSize()
        );

        if (rotatedScaled != null)
        {
            playerPoint.setImage(rotatedScaled);
        }
    }

    private void ensurePointExists()
    {
        if (playerPoint != null)
        {
            return;
        }

        Player p = client.getLocalPlayer();
        if (p == null || baseArrow == null)
        {
            return;
        }

        BufferedImage initial = ImageUtil.rotateAndScale(
                baseArrow,
                p.getCurrentOrientation() * Perspective.UNIT,
                config.worldMapIconSize()
        );

        playerPoint = new WorldMapPoint(p.getWorldLocation(), initial);
        playerPoint.setSnapToEdge(false);
        playerPoint.setJumpOnClick(false);

        worldMapPointManager.add(playerPoint);
    }

    private void removePoint()
    {
        if (playerPoint != null)
        {
            worldMapPointManager.remove(playerPoint);
            playerPoint = null;
        }
    }
}

package com.MapPlayerIndicator;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup("MapPlayerIndicator")
public interface PlayerIndicatorConfig extends Config
{
	@ConfigItem(
			keyName = "worldMapIconSize",
			name = "World map icon size",
			description = "Rendered size in pixels of the world map arrow."
	)
	default int worldMapIconSize()
	{
		return 42;
	}

	@ConfigItem(
			keyName = "worldMapEnabled",
			name = "Enable world map arrow",
			description = "Show the custom arrow on the world map."
	)
	default boolean worldMapEnabled()
	{
		return true;
	}
}

package com.MapPlayerIndicator;

import com.MapPlayerIndicator.overlay.PlayerIndicatorWorldMapOverlay;
import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
		name = "World Map Player Indicator",
		description = "Places an arrow indicator for the characters facing direction on the world map.",
		tags = {"world", "player", "character", "indicator", "map", "direction", "arrow"}
)
public class PlayerIndicatorPlugin extends Plugin
{
	@Inject private PlayerIndicatorWorldMapOverlay worldMapIndicator;

	@Provides
	PlayerIndicatorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PlayerIndicatorConfig.class);
	}

	@Override
	protected void startUp()
	{
		worldMapIndicator.startUp();
	}

	@Override
	protected void shutDown()
	{
		worldMapIndicator.shutDown();
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		worldMapIndicator.onGameTick();
	}
}

package com.MapPlayerIndicator;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;

public final class ImageUtil
{
    private ImageUtil() {}

    public static BufferedImage rotateAndScale(BufferedImage src, double radians, int outSize)
    {
        if (src == null || outSize <= 0)
        {
            return null;
        }

        BufferedImage out = new BufferedImage(outSize, outSize, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            double cx = outSize / 2.0;
            double cy = outSize / 2.0;

            AffineTransform at = new AffineTransform();
            at.translate(cx, cy);
            at.rotate(radians);

            double sx = (double) outSize / src.getWidth();
            double sy = (double) outSize / src.getHeight();
            at.scale(sx, sy);

            at.translate(-src.getWidth() / 2.0, -src.getHeight() / 2.0);

            g.drawImage(src, at, null);
        }
        finally
        {
            g.dispose();
        }
        return out;
    }
}
